SELECT tblEingabeUnGruppe.Gruppe, tblEingabeUnGruppe.Datum, tblEingabeUnGruppe.Zeit, qryVAnolytGruppe.VAnolyt, EtaNaClO3Ber([Analyse Anolyt Gruppe]![NaClO3 An],[VAnolyt],[Analyse Pure Brine Gruppe]![NaClO3 Pb],[Analyse Pure Brine Gruppe]![flow rate],[tblEingabeUnGruppe]![n],[tblEingabeUnGruppe]![I Gesamt]) AS µNaClO3, EtaNaOClBer([Analyse Anolyt Gruppe]![NaOCl An],[VAnolyt],[tblEingabeUnGruppe]![n],[tblEingabeUnGruppe]![I Gesamt]) AS µNaOCl, EtaAlkaliBer([Analyse Pure Brine Gruppe]![NaOH Pb],[Analyse Pure Brine Gruppe]![flow rate],[tblEingabeUnGruppe]![n],[tblEingabeUnGruppe]![I Gesamt]) AS µAlkali, EtaNa2CO3Ber([Analyse Pure Brine Gruppe]![Na2CO3 Pb],[Analyse Pure Brine Gruppe]![flow rate],[tblEingabeUnGruppe]![n],[tblEingabeUnGruppe]![I Gesamt]) AS µNa2CO3, EtaHClBer([Analyse Pure Brine Gruppe]![HCl Pb],[Analyse Pure Brine Gruppe]![flow rate],[Analyse Anolyt Gruppe]![HCl An],[VAnolyt],[tblEingabeUnGruppe]![n],[tblEingabeUnGruppe]![I Gesamt]) AS µHCl, EtaO2Ber([Analyse Chlorgas Gruppe]![O2 Cl],[Analyse Chlorgas Gruppe]![Cl2 + CO2 Cl],[µNaClO3],[µNaOCl]) AS µO2, EtaO2Ber([Analyse Chlorgas Gruppe]![O2 Cl],[Analyse Chlorgas Gruppe]![Cl2 + CO2 Cl],[µNaClO3],[µNaOCl]) AS µO2alt, EtaMembraneBer([µO2],[µNaClO3],[µNaOCl],[µHCl],[µNa2CO3],[µAlkali]) AS µNaOH, GEtGewAKF() AS CheckAKF, AktOClAnalyse() AS CheckClO, AktAnsaeurung() AS CheckAnsaeurung, EtaNaOClBer([Analyse Anolyt Gruppe]![NaOCl An],[VAnolyt],[tblEingabeUnGruppe]![n],[tblEingabeUnGruppe]![I Gesamt]) AS Ausdr1, EtaNaClO3Ber([Analyse Anolyt Gruppe]![NaClO3 An],[VAnolyt],[Analyse Pure Brine Gruppe]![NaClO3 Pb],[Analyse Pure Brine Gruppe]![flow rate],[tblEingabeUnGruppe]![n],[tblEingabeUnGruppe]![I Gesamt]) AS Ausdr2
FROM tblGewDaten, qryVAnolytGruppe INNER JOIN (tblEingabeUnGruppe INNER JOIN (([Analyse Pure Brine Gruppe] INNER JOIN [Analyse Anolyt Gruppe] ON ([Analyse Pure Brine Gruppe].Datum = [Analyse Anolyt Gruppe].Datum) AND ([Analyse Pure Brine Gruppe].Gruppe = [Analyse Anolyt Gruppe].Gruppe)) INNER JOIN [Analyse Chlorgas Gruppe] ON ([Analyse Anolyt Gruppe].Datum = [Analyse Chlorgas Gruppe].Datum) AND ([Analyse Anolyt Gruppe].Gruppe = [Analyse Chlorgas Gruppe].Gruppe)) ON (tblEingabeUnGruppe.Datum = [Analyse Pure Brine Gruppe].Datum) AND (tblEingabeUnGruppe.Gruppe = [Analyse Pure Brine Gruppe].Gruppe)) ON (qryVAnolytGruppe.Datum = tblEingabeUnGruppe.Datum) AND (qryVAnolytGruppe.Gruppe = tblEingabeUnGruppe.Gruppe)
WHERE (((tblEingabeUnGruppe.Datum)>=[tblGewDaten].[Anfangsdatum] And (tblEingabeUnGruppe.Datum)<=[tblGewDaten].[Enddatum]) AND ((qryVAnolytGruppe.VAnolyt)<>(-1)) AND ((EtaNaClO3Ber([Analyse Anolyt Gruppe]![NaClO3 An],[VAnolyt],[Analyse Pure Brine Gruppe]![NaClO3 Pb],[Analyse Pure Brine Gruppe]![flow rate],[tblEingabeUnGruppe]![n],[tblEingabeUnGruppe]![I Gesamt]))<>(-1)) AND ((EtaNaOClBer([Analyse Anolyt Gruppe]![NaOCl An],[VAnolyt],[tblEingabeUnGruppe]![n],[tblEingabeUnGruppe]![I Gesamt]))<>(-1)) AND ((EtaAlkaliBer([Analyse Pure Brine Gruppe]![NaOH Pb],[Analyse Pure Brine Gruppe]![flow rate],[tblEingabeUnGruppe]![n],[tblEingabeUnGruppe]![I Gesamt]))<>(-1)) AND ((EtaNa2CO3Ber([Analyse Pure Brine Gruppe]![Na2CO3 Pb],[Analyse Pure Brine Gruppe]![flow rate],[tblEingabeUnGruppe]![n],[tblEingabeUnGruppe]![I Gesamt]))<>(-1)) AND ((EtaHClBer([Analyse Pure Brine Gruppe]![HCl Pb],[Analyse Pure Brine Gruppe]![flow rate],[Analyse Anolyt Gruppe]![HCl An],[VAnolyt],[tblEingabeUnGruppe]![n],[tblEingabeUnGruppe]![I Gesamt]))<>(-1)))
ORDER BY tblEingabeUnGruppe.Datum;
